package com.fasterxml.jackson.core.json;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonFactory;
import com.fasterxml.jackson.core.JsonGenerator;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.core.base.ParserBase;
import com.fasterxml.jackson.core.io.CharTypes;
import com.fasterxml.jackson.core.io.IOContext;
import com.fasterxml.jackson.core.io.SegmentedStringifier;
import com.fasterxml.jackson.core.io.SerializableString;
import com.fasterxml.jackson.core.sym.CharsToNameCanonicalizer;
import com.fasterxml.jackson.core.util.*;
import java.io.*;
import java.io.IOException;
import java.io.StringReader;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for ReaderBasedJsonParser#nextFieldName
 */
public class ReaderBasedJsonParser_nextFieldName_TriageGen0Test {

    private JsonFactory factory;

    @Before
    public void setUp() {
        factory = new JsonFactory();
    }

    private SerializableString sstr(String s) {
        return SegmentedStringifier.newStringifier(s);
    }

    @Test
    public void testNextFieldName_MatchSuccess() throws IOException {
        String json = "{\"name\":\"value\"}";
        JsonParser parser = factory.createParser(new StringReader(json));

        parser.nextToken(); // Move to START_OBJECT

        boolean found = parser.nextFieldName(sstr("name"));
        assertTrue("Should return true when field name matches", found);

        JsonToken token = parser.nextToken();
        assertEquals(JsonToken.VALUE_STRING, token);
        assertEquals("value", parser.getText());
    }

    @Test
    public void testNextFieldName_NoMatch() throws IOException {
        String json = "{\"other\":\"value\"}";
        JsonParser parser = factory.createParser(new StringReader(json));

        parser.nextToken(); // START_OBJECT

        boolean found = parser.nextFieldName(sstr("name"));
        assertFalse("Should return false when field name does not match", found);
    }

    @Test
    public void testNextFieldName_AlreadyAtFieldName() throws IOException {
        String json = "{\"name\":\"value\"}";
        JsonParser parser = factory.createParser(new StringReader(json));

        parser.nextToken(); // START_OBJECT
        parser.nextToken(); // FIELD_NAME "name"

        // The code says: if (_currToken == JsonToken.FIELD_NAME) { _nextAfterName(); return false; }
        boolean found = parser.nextFieldName(sstr("name"));
        assertFalse("Should return false if current token is already a FIELD_NAME", found);

        // Verify it moved past the name to the value
        assertEquals(JsonToken.VALUE_STRING, parser.getCurrentToken());
    }

    @Test
    public void testNextFieldName_EndOfObject() throws IOException {
        String json = "{}";
        JsonParser parser = factory.createParser(new StringReader(json));

        parser.nextToken(); // START_OBJECT

        // After START_OBJECT, next field name looks for a name or END_OBJECT
        // In {}, the next token is END_OBJECT
        boolean found = parser.nextFieldName(sstr("any"));
        assertFalse("Should return false when encountering END_OBJECT", found);
        assertEquals(JsonToken.END_OBJECT, parser.getCurrentToken());
    }

    @Test
    public void testNextFieldName_EndOfArrayMismatched() throws IOException {
        // Testing the branch where i == INT_RBRACKET but not in array context
        // This tests the _reportMismatchedEndMarker(i, '}') branch
        String json = "[ ]"; 
        // We need to force a state where we are in an array but nextFieldName finds a ']'
        // However, nextFieldName checks if (!parsingContext.inObject()) -> _nextTokenNotInObject
        // Let's test the case where we are not in an object and call nextFieldName
        JsonParser parser = factory.createParser(new StringReader("[1,2,3]"));
        parser.nextToken(); // START_ARRAY

        try {
            parser.nextFieldName(sstr("test"));
            fail("Should have thrown exception because nextFieldName is called outside an object");
        } catch (IOException e) {
            // Expected
        }
    }

    @Test
    public void testNextFieldName_WithWhitespaceAndComma() throws IOException {
        String json = "{\n  \"key\"  :  \"value\" \n}";
        JsonParser parser = factory.createParser(new StringReader(json));

        parser.nextToken(); // START_OBJECT

        boolean found = parser.nextFieldName(sstr("key"));
        assertTrue(found);

        parser.nextToken(); // VALUE_STRING
        assertEquals("value", parser.getText());
    }

    @Test
    public void testNextFieldName_EndOfStringIncomplete() throws IOException {
        // Testing the _tokenIncomplete / _skipString branch
        // This is hard to trigger via standard parser usage as it's an internal state,
        // but we can simulate a malformed JSON where a string is not closed if the parser allows.
        // For standard unit tests, we ensure normal flow handles whitespace.
        String json = "{ \"a\" : 1 , \"b\" : 2 }";
        JsonParser parser = factory.createParser(new StringReader(json));
        parser.nextToken(); // START_OBJECT

        assertTrue(parser.nextFieldName(sstr("a")));
        parser.nextToken(); // 1

        assertTrue(parser.nextFieldName(sstr("b")));
        parser.nextToken(); // 2
    }

    @Test
    public void testNextFieldName_EndofInput() throws IOException {
        String json = "{";
        JsonParser parser = factory.createParser(new StringReader(json));
        parser.nextToken(); // START_OBJECT

        // At end of input
        boolean found = parser.nextFieldName(sstr("any"));
        assertFalse(found);
        assertNull(parser.getCurrentToken());
    }

    @Test
    public void testNextFieldName_FastPathMatch() throws IOException {
        // The code has a specific optimization for (i == INT_QUOTE) 
        // where it checks (len + 4) < _inputEnd and matches characters manually.
        String json = "{\"longFieldName\":\"value\"}";
        JsonParser parser = factory.createParser(new StringReader(json));
        parser.nextToken(); // START_OBJECT

        // This should trigger the manual char-by-char comparison loop
        boolean found = parser.nextFieldName(sstr("longFieldName"));
        assertTrue(found);
        assertEquals(JsonToken.VALUE_STRING, parser.nextToken());
    }
}
